from typing import Any
from typing import TextIO
import csv
import io

import pandas as pd

REQUIRED_COLUMNS = ('name', 'email', 'role')
VALID_ROLES = ('admin', 'editor', 'viewer')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


# pcat: importers.users_csv.parse@v1
# pcat-allow: PC109 -- the request requires a validated 'role' column, so REQUIRED_COLUMNS gains 'role'
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        role = (row.get('role') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if not role:
            problems.append('role is required')
        elif role not in VALID_ROLES:
            problems.append(f"role must be one of: {', '.join(VALID_ROLES)}")
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'role': role, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def upload_to_csv_text(content: bytes, filename: str, max_rows: int = MAX_ROWS) -> str:
    """Turn an uploaded .csv or .xlsx into CSV text (all cells kept as strings)."""
    name = filename.lower()
    if name.endswith('.csv'):
        return content.decode('utf-8-sig')
    if name.endswith(('.xlsx', '.xlsm')):
        frame = pd.read_excel(io.BytesIO(content), dtype=str, keep_default_na=False, nrows=max_rows + 1)
        return frame.to_csv(index=False)
    raise ValueError('unsupported file type; upload a .csv or .xlsx file')


def validate_users_upload(content: bytes, filename: str, max_rows: int = MAX_ROWS) -> list[dict[str, Any]]:
    """Return every bad row as {'row': spreadsheet row number (header is row 1), 'errors': [reasons]}."""
    try:
        text = upload_to_csv_text(content, filename, max_rows)
    except Exception as exc:
        return [{'row': 1, 'errors': [f'could not read file: {type(exc).__name__}']}]
    return import_users(text, max_rows)[1]


# ---------------------------------------------------------------- tests (pytest)

def _csv_bytes(text: str) -> bytes:
    return text.encode('utf-8')


def test_reports_all_problems_with_row_numbers():
    data = _csv_bytes(
        'name,email,role\n'
        'Ann,ann@example.com,admin\n'        # row 2 ok
        ',not-an-email,boss\n'               # row 3: three problems
        'Bob,ANN@example.com,viewer\n'       # row 4: duplicate
        'Cy,cy@example.com,\n'               # row 5: missing role
    )
    result = {e['row']: e['errors'] for e in validate_users_upload(data, 'users.csv')}
    assert set(result) == {3, 4, 5}
    assert 'name is required' in result[3]
    assert 'email is invalid' in result[3]
    assert any(m.startswith('role must be one of') for m in result[3])
    assert result[4] == ['duplicate email']
    assert result[5] == ['role is required']


def test_valid_file_has_no_errors():
    data = _csv_bytes('name,email,role,age\nAnn,ann@example.com,Editor,30\n')
    assert validate_users_upload(data, 'ok.csv') == []


def test_missing_column_and_bad_age():
    assert validate_users_upload(_csv_bytes('name,email\nAnn,a@b.co\n'), 'x.csv') == [
        {'row': 1, 'errors': ['missing columns: role']}
    ]
    bad_age = _csv_bytes('name,email,role,age\nAnn,a@b.co,admin,200\n')
    assert validate_users_upload(bad_age, 'x.csv')[0]['errors'] == ['age must be a whole number from 0 to 150']


def test_xlsx_upload():
    import pytest
    pytest.importorskip('openpyxl')
    buffer = io.BytesIO()
    pd.DataFrame(
        {'Name': ['Ann', 'Bob'], 'Email': ['ann@example.com', 'bad'], 'Role': ['admin', 'viewer']}
    ).to_excel(buffer, index=False)
    errors = validate_users_upload(buffer.getvalue(), 'users.xlsx')
    assert errors == [{'row': 3, 'errors': ['email is invalid']}]


def test_unsupported_file_type():
    errors = validate_users_upload(b'whatever', 'users.pdf')
    assert errors[0]['row'] == 1 and 'could not read file' in errors[0]['errors'][0]

